import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, sin, float } from 'three/tsl';
import { gsap } from 'gsap';

function hexRgb(value, fallback) {
  const source = typeof value === 'string' ? value : fallback;
  const hex = source.replace('#', '');
  if (hex.length !== 6) return [0, 0, 0];
  return [
    parseInt(hex.slice(0, 2), 16) / 255,
    parseInt(hex.slice(2, 4), 16) / 255,
    parseInt(hex.slice(4, 6), 16) / 255
  ];
}

function makeGradientMaterial(colors) {
  const top = vec3(...hexRgb(colors.paper, '#e8ecf2')).mul(0.16);
  const middle = vec3(...hexRgb(colors.ink, '#16161d')).mul(0.72);
  const bottom = vec3(...hexRgb(colors.surface, '#0b0b10'));

  const vertical = uv().y;
  const upperBlend = smoothstep(float(0.18), float(0.72), vertical);
  const lowerBlend = smoothstep(float(0.04), float(0.52), vertical);
  const upper = mix(bottom, middle, lowerBlend);
  const gradient = mix(upper, top, upperBlend);

  const grain = sin(
    uv().x.mul(241.0).add(uv().y.mul(173.0))
  ).mul(0.008);

  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    toneMapped: true
  });

  material.colorNode = gradient.add(vec3(grain, grain, grain));
  return material;
}

function makeSolidMaterial(color, opacity = 1) {
  return new MeshBasicNodeMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthWrite: opacity >= 1,
    toneMapped: true
  });
}

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry } = THREE;

  const root = new Group();
  root.name = 'pricing-title';

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = {
    ink: visualSpec.colors?.ink ?? '#16161d',
    paper: visualSpec.colors?.paper ?? '#e8ecf2',
    accent: visualSpec.colors?.accent ?? '#ff2a38',
    surface: visualSpec.colors?.surface ?? '#0b0b10'
  };

  const geometries = [];
  const materials = [];
  const resources = [];
  const timelines = [];
  let disposed = false;

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = makeGradientMaterial(colors);
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  geometries.push(backdropGeometry);
  materials.push(backdropMaterial);

  const surfaceGeometry = new PlaneGeometry(5.9, 2.9);
  const surfaceMaterial = makeSolidMaterial(colors.ink, 0.96);
  const surface = new Mesh(surfaceGeometry, surfaceMaterial);
  surface.name = 'machined-surface';
  surface.position.set(0, 0.12, -1.55);
  root.add(surface);
  geometries.push(surfaceGeometry);
  materials.push(surfaceMaterial);

  const insetGeometry = new PlaneGeometry(5.35, 2.35);
  const insetMaterial = makeGradientMaterial(colors);
  const inset = new Mesh(insetGeometry, insetMaterial);
  inset.name = 'textured-inset-plane';
  inset.position.set(0, 0.12, -1.42);
  root.add(inset);
  geometries.push(insetGeometry);
  materials.push(insetMaterial);

  const accentGeometry = new PlaneGeometry(1.35, 0.035);
  const accentMaterial = makeSolidMaterial(colors.accent);
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.name = 'signal-red-accent';
  accent.position.set(-2.08, -0.78, -0.85);
  root.add(accent);
  geometries.push(accentGeometry);
  materials.push(accentMaterial);

  const items = config.textContent ?? visualSpec.textContent ?? [];
  const textObjects = [];

  for (const item of items) {
    const text = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 96,
      color: colors.paper,
      align: 'center',
      maxWidthPx: 900
    });

    text.name = item.role === 'headline' ? 'pricing-headline' : 'pricing-text';
    text.position.set(0, 0.12, -0.55);
    root.add(text);
    textObjects.push(text);
  }

  if (config.imageUrl && ctx.textureLoader?.loadTexture) {
    const imageGeometry = new PlaneGeometry(4.75, 2.97);
    const imageMaterial = new MeshBasicNodeMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 0.055,
      depthWrite: false,
      toneMapped: true
    });
    const imagePlane = new Mesh(imageGeometry, imageMaterial);
    imagePlane.name = 'isolated-atlas-texture';
    imagePlane.position.set(0, 0.12, -1.25);
    root.add(imagePlane);
    geometries.push(imageGeometry);
    materials.push(imageMaterial);

    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
      resources.push(texture);
    }).catch(() => {});
  }

  const entrance = gsap.timeline();
  timelines.push(entrance);

  for (const text of textObjects) {
    entrance.fromTo(
      text.scale,
      { x: 1.04, y: 1.04, z: 1.04 },
      { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
      0
    );
    entrance.fromTo(
      text.position,
      { y: 0.42 },
      { y: 0.12, duration: 0.7, ease: 'power3.out' },
      0
    );
  }

  entrance.fromTo(
    accent.scale,
    { x: 0 },
    { x: 1, duration: 0.6, ease: 'power3.out' },
    0.18
  );

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline.kill();
    }

    for (const resource of resources) {
      resource.dispose?.();
    }

    for (const text of textObjects) {
      text.userData?.cleanup?.();
      text.dispose?.();
    }

    for (const geometry of geometries) {
      geometry.dispose();
    }

    for (const material of materials) {
      material.dispose();
    }
  };

  return root;
}
